// ===== 카페24: 주문 수집 + 전처리 (최종) =====
const pages = $('주문 조회1').all();
let orders = [];
for (const p of pages) {
  const arr = Array.isArray(p.json.orders) ? p.json.orders : [];
  orders = orders.concat(arr);
}

const num = (v) => { const n = Number(v); return isNaN(n) ? 0 : n; };

// 규칙 1: 이모지, 영문, ',', '.' 제거
const clean = (s) => String(s == null ? '' : s)
  .replace(/[A-Za-z]/g, '')
  .replace(/[\p{Extended_Pictographic}\uFE0F\u200D]/gu, '')
  .replace(/[,.]/g, '')
  .replace(/\s{2,}/g, ' ')
  .trim();
const stripEmojiOnly = (s) => String(s == null ? '' : s)
  .replace(/[\p{Extended_Pictographic}\uFE0F\u200D]/gu, '')
  .replace(/\s{2,}/g, ' ')
  .trim();

const optVal = (opt, key) => {
  const m = String(opt == null ? '' : opt).match(new RegExp(key + '[^=]*=\\s*([^,]+)'));
  return m ? m[1].trim() : '';
};
const stripQty = (v) => clean(String(v).replace(/\([^()]*\)/g, ' ')).replace(/\s*1개$/, '').trim();
const setVal = (opt) => {
  let s = String(opt == null ? '' : opt);
  let i = s.lastIndexOf('='); if (i < 0) return '';
  s = s.slice(i + 1);
  i = s.lastIndexOf(':'); if (i >= 0) s = s.slice(i + 1);
  return clean(s);
};

// 하드코딩 매핑 (특수 상품 예외)
const HARDCODE = [
  { test: /김스낵 간식 선물세트\s*\(\s*8입\s*\)/, name: '김스낵-혼합 8입' }
];

// 건어물 어종 키워드 — 신규 어종 출시 시 여기에 단어만 추가
// ⚠ 순서 중요: 긴 이름 먼저 (버터오징어·숏다리가 오징어보다 앞)
const DRIED = ['버터오징어', '숏다리', '쥐포', '아귀', '오징어'];

// 상품명 표준화
const nameOf = (nameRaw, optRaw) => {
  for (const h of HARDCODE) { if (h.test.test(nameRaw)) return h.name; }
  // 콜라보: {X 앞 브랜드명}-{품목}-{수량값}
  const xm = nameRaw.match(/^(.*?)\sX\s/);
  if (xm) {
    let brand = clean(xm[1]);
    if (!brand) brand = stripEmojiOnly(xm[1]);
    const item = clean(optVal(optRaw, '품목'));
    let v = stripQty(optVal(optRaw, '수량'));
    if (brand && item && v) {
      if (v.startsWith(item + ' ')) v = v.slice(item.length).trim();
      return brand + '-' + item + '-' + v;
    }
    return clean(nameRaw);
  }
  const hasSet = nameRaw.includes('세트');
  const pm = clean(optVal(optRaw, '제품명'));
  const sv = setVal(optRaw);
  let n = null;
  if (nameRaw.includes('김')) {
    if (hasSet && sv) n = '김스낵-' + sv;
    else if (!hasSet && pm) n = '김스낵-' + pm;
  }
  if (!n && nameRaw.includes('건어물')) {
    if (hasSet && sv) n = '건어물-' + sv;
    else if (!hasSet && pm) n = '건어물-' + pm;
  }
  // 건어물 키워드 폴백: 상품명에 '건어물'이 없는 단품 대응
  if (!n && !nameRaw.includes('세트')) {
    for (const k of DRIED) { if (nameRaw.includes(k)) { n = '건어물-' + k; break; } }
  }
  if (!n) n = clean(nameRaw);
  return n.replace(/선물세트/g, '').replace(/\s{2,}/g, ' ').replace(/[\s-]+$/, '').trim();
};

const rows = [];
for (const o of orders) {
  const init = o.initial_order_amount || {};
  const act = o.actual_order_amount || {};

  const totalOrder = num(init.total_amount_due)
    || (num(init.order_price_amount) + num(init.shipping_fee))
    || num(o.order_price_amount);
  const totalPaid = o.payment_amount != null ? num(o.payment_amount) : num(act.payment_amount);
  const paid = o.paid || '';

  if (paid === 'T' && totalPaid === 0) continue; // 테스트 주문 제거
  if (paid === 'F') continue;                    // 미결제 제거

  const items = Array.isArray(o.items) ? o.items : [];
  items.forEach((it, idx) => {
    const nameRaw = String(it.product_name || it.product_name_default || '');
    const optRaw = String(it.option_value || '');
    const unitPrice = num(it.product_price) + num(it.option_price);
    const qty = num(it.quantity);
    rows.push({ json: {
      '주문일': String(o.order_date || '').slice(0, 19).replace('T', ' '),
      '주문번호': o.order_id || '',
      '품목별 주문번호': it.order_item_code || ((o.order_id || '') + '-' + String(idx + 1).padStart(2, '0')),
      '총 주문금액': totalOrder,
      '총 결제금액': totalPaid,
      '주문상품명(옵션포함)': nameOf(nameRaw, optRaw),
      '수량': qty,
      '판매가': unitPrice,
      '상품별판매액': unitPrice * qty,
      '결제구분': paid
    } });
  });
}

rows.sort((a, b) => a.json['주문일'] < b.json['주문일'] ? -1 : a.json['주문일'] > b.json['주문일'] ? 1 : 0);
return rows;

// 공개 자료 검토 시 중복 삽입된 앞부분을 제거함. 다른 동작은 유지.
const BACKFILL_START = '2025-06-01';
const BACKFILL_END   = '';

const fmt = (d) => new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Seoul' }).format(d);
const today = fmt(new Date());

const isEditorRun = ['manual', 'test'].includes(String($execution.mode));

if (!isEditorRun) {
  const weekAgo = fmt(new Date(Date.now() - 6 * 86400000));
  return [{ json: { start_date: weekAgo, end_date: today } }];
}

const toUTC = (str) => { const [y, m, d] = str.split('-').map(Number); return Date.UTC(y, m - 1, d, 12); };
const toStr = (ms) => new Date(ms).toISOString().slice(0, 10);
const DAY = 86400000;

const endMs = toUTC(BACKFILL_END || today);
let sMs = toUTC(BACKFILL_START);
const out = [];
while (sMs <= endMs) {
  const d = new Date(sMs);
  const monthEndMs = Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + 1, 0, 12);
  const chunkEndMs = Math.min(monthEndMs, endMs);
  out.push({ json: { start_date: toStr(sMs), end_date: toStr(chunkEndMs) } });
  sMs = chunkEndMs + DAY;
}
return out;

// ===== 네이버: 칼럼 선택 + 행 필터 + 상품명 전처리 (최종) =====
const num = (v) => { const n = Number(v); return isNaN(n) ? 0 : n; };

const normDT = (v) => {
  if (v == null || v === '') return '';
  if (typeof v === 'number' && v > 20000) {
    return new Date(Math.round((v - 25569) * 86400000)).toISOString().slice(0, 19).replace('T', ' ');
  }
  const s = String(v).trim();
  const m = s.match(/(\d{4})[.\-\/\s]+(\d{1,2})[.\-\/\s]+(\d{1,2})/);
  if (m) {
    const time = (s.match(/\d{1,2}:\d{2}(:\d{2})?/) || [''])[0];
    return m[1] + '-' + m[2].padStart(2, '0') + '-' + m[3].padStart(2, '0') + (time ? ' ' + time : '');
  }
  return s;
};

const clean = (s) => String(s == null ? '' : s)
  .replace(/[A-Za-z]/g, '')
  .replace(/[\p{Extended_Pictographic}\uFE0F\u200D]/gu, '')
  .replace(/[,.]/g, '')
  .replace(/\s{2,}/g, ' ')
  .trim();

const prodValue = (optRaw) => {
  const m = String(optRaw == null ? '' : optRaw).match(/제품명\s*[:=]\s*([^,\/|]+)/);
  return m ? clean(m[1]) : '';
};
const afterLastColon = (optRaw) => {
  const s = String(optRaw == null ? '' : optRaw);
  const i = s.lastIndexOf(':');
  return i >= 0 ? clean(s.slice(i + 1)) : '';
};

// 하드코딩 매핑 (특수 상품 예외)
const HARDCODE = [
  { test: /김스낵 간식 선물세트\s*\(\s*8입\s*\)/, name: '김스낵-혼합 8입' }
];

// 건어물 어종 키워드 — 신규 어종 출시 시 여기에 단어만 추가 (긴 이름 먼저)
const DRIED = ['버터오징어', '숏다리', '쥐포', '아귀', '오징어'];

const nameOf = (nameRaw, optRaw) => {
  for (const h of HARDCODE) { if (h.test.test(nameRaw)) return h.name; }
  const hasSet = nameRaw.includes('세트');
  let n = null;
  if (nameRaw.includes('김')) {
    if (hasSet) { const t = afterLastColon(optRaw); if (t) n = '김스낵-' + t; }
    else { const v = prodValue(optRaw); if (v) n = '김스낵-' + v; }
  }
  if (!n && nameRaw.includes('건어물')) {
    if (hasSet) { const t = afterLastColon(optRaw); if (t) n = '건어물-' + t; }
    else { const v = prodValue(optRaw); if (v) n = '건어물-' + v; }
  }
  // 건어물 키워드 폴백
  if (!n && !nameRaw.includes('세트')) {
    for (const k of DRIED) { if (nameRaw.includes(k)) { n = '건어물-' + k; break; } }
  }
  if (!n) n = clean(nameRaw);
  return n.replace(/선물세트/g, '').replace(/\s{2,}/g, ' ').replace(/[\s-]+$/, '').trim();
};

const out = [];
for (const item of $input.all()) {
  const r = item.json;
  const pon = String(r['상품주문번호'] == null ? '' : r['상품주문번호']).trim();
  if (!pon) continue;

  const claim = String(r['클레임상태'] == null ? '' : r['클레임상태']).trim();
  if (claim === '취소철회') continue;
  if (String(r['주문상태'] == null ? '' : r['주문상태']).trim() !== '구매확정') continue;

  const nameRaw = String(r['상품명'] == null ? '' : r['상품명']);
  const optRaw = String(r['옵션정보'] == null ? '' : r['옵션정보']);

  out.push({ json: {
    '상품주문번호': pon,
    '주문일시': normDT(r['주문일시']),
    '주문상태': String(r['주문상태'] == null ? '' : r['주문상태']).trim(),
    '클레임상태': claim,
    '상품명': nameOf(nameRaw, optRaw),
    '옵션정보': optRaw.trim(),
    '수량': num(r['수량'])
  } });
}

out.sort((a, b) => a.json['주문일시'] < b.json['주문일시'] ? -1 : a.json['주문일시'] > b.json['주문일시'] ? 1 : 0);
return out;

// KPI4는 '월 단위' 집계이므로 기간도 월 단위로 만든다.
// 스케줄 실행(production) = 지난달 전체 + 이번 달 1일~오늘 (매일 두 달치를 재집계 → upsert로 덮어씀)
// 에디터 수동 실행 = BACKFILL_START ~ BACKFILL_END 를 월 단위로 쪼개서 전체 백필
const BACKFILL_START = '2025-01-01';
const BACKFILL_END   = ''; // 비우면 오늘까지

const fmt = (d) => new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Seoul' }).format(d);
const today = fmt(new Date());

if ($execution.mode === 'production') {
  const [y, m] = today.split('-').map(Number);
  const py = m === 1 ? y - 1 : y;
  const pm = m === 1 ? 12 : m - 1;
  const lastDay = new Date(Date.UTC(py, pm, 0, 12)).getUTCDate();
  const mm = String(pm).padStart(2, '0');
  return [
    { json: { start_date: `${py}-${mm}-01`, end_date: `${py}-${mm}-${String(lastDay).padStart(2, '0')}` } },
    { json: { start_date: today.slice(0, 7) + '-01', end_date: today } }
  ];
}

// 월 단위 청크 생성 — 서버 시간대 영향이 없도록 전부 UTC 정오 기준으로 계산
const toUTC = (str) => { const [y, m, d] = str.split('-').map(Number); return Date.UTC(y, m - 1, d, 12); };
const toStr = (ms) => new Date(ms).toISOString().slice(0, 10);
const DAY = 86400000;

const endMs = toUTC(BACKFILL_END || today);
let sMs = toUTC(BACKFILL_START);
const out = [];
while (sMs <= endMs) {
  const d = new Date(sMs);
  const monthEndMs = Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + 1, 0, 12);
  const chunkEndMs = Math.min(monthEndMs, endMs);
  out.push({ json: { start_date: toStr(sMs), end_date: toStr(chunkEndMs) } });
  sMs = chunkEndMs + DAY;
}
return out;

// 주문에서 유효 주문만 남기고, 회원 주문의 member_id 목록을 100개 단위로 묶는다.
// (customersprivacy는 member_id를 콤마로 최대 100개까지 동시 조회 가능)
const pages = $('주문 조회').all();
let orders = [];
for (const p of pages) {
  const arr = Array.isArray(p.json.orders) ? p.json.orders : [];
  orders = orders.concat(arr);
}

const num = (v) => { const n = Number(v); return isNaN(n) ? 0 : n; };
const memberIds = new Set();

for (const o of orders) {
  const act = o.actual_order_amount || {};
  const totalPaid = o.payment_amount != null ? num(o.payment_amount) : num(act.payment_amount);
  const paid = o.paid || '';
  // 전처리: 테스트 주문(T + 0원) / 미결제(F) 제거
  if (paid === 'T' && totalPaid === 0) continue;
  if (paid === 'F') continue;
  if (o.member_id) memberIds.add(String(o.member_id));
}

const ids = [...memberIds];
const out = [];
for (let i = 0; i < ids.length; i += 100) {
  out.push({ json: { member_ids: ids.slice(i, i + 100).join(',') } });
}
// 회원 주문이 하나도 없어도 다음 노드가 실행되도록 더미 1건 유지
if (out.length === 0) out.push({ json: { member_ids: '' } });
return out;

// 주문 × 회원정보 조인 → 월 × 성별 × 연령대 집계 (KPI 4)
// 네이버 리포트와 동일한 축을 사용한다:
//  - row_key = 월_성별_연령대 (예: 2026-06_여성_40대)
//  - 연령대: 10대 이하 / 20대 / 30대 / 40대 / 50대 / 60대 이상 / 알수없음
//  - 비회원·정보없음(생년월일/성별 미확인)은 모두 '알수없음' 단일 버킷으로 합산
//  - 매월 13개 조합(남성6+여성6+알수없음1)을 구매가 없어도 0으로 모두 생성
// PII(생년월일 등)는 시트에 저장하지 않고 여기서 버킷팅 후 폐기한다.

// 1) 회원정보 맵 구성
const privPages = $input.all();
const memberMap = {};
for (const p of privPages) {
  const arr = (p.json && Array.isArray(p.json.customersprivacy)) ? p.json.customersprivacy : [];
  for (const c of arr) {
    if (c.member_id) memberMap[String(c.member_id)] = { birthday: c.birthday || '', gender: c.gender || '' };
  }
}

// 2) 주문 로드
const pages = $('주문 조회').all();
let orders = [];
for (const p of pages) {
  const arr = Array.isArray(p.json.orders) ? p.json.orders : [];
  orders = orders.concat(arr);
}

const num = (v) => { const n = Number(v); return isNaN(n) ? 0 : n; };
const genderKo = (g) => {
  const s = String(g || '').trim().toUpperCase();
  if (s === 'M' || s === 'MALE' || s === '남' || s === '남성') return '남성';
  if (s === 'F' || s === 'FEMALE' || s === '여' || s === '여성') return '여성';
  return '알수없음';
};
const ageBucket = (birthday, orderDate) => {
  const by = Number(String(birthday).slice(0, 4));
  const oy = Number(String(orderDate).slice(0, 4));
  if (!by || !oy || by < 1900) return '알수없음';
  const age = oy - by; // 연 나이 기준(가정) — 관리자 통계와 오차 가능
  if (age < 20) return '10대 이하';
  if (age >= 60) return '60대 이상';
  return Math.floor(age / 10) * 10 + '대';
};

// 3) 집계: key = 월|성별|연령
const agg = {};
const seenOrder = new Set();
const monthsWithData = new Set();
for (const o of orders) {
  const oid = o.order_id || '';
  if (oid && seenOrder.has(oid)) continue; // 페이지 중복 방어
  if (oid) seenOrder.add(oid);

  const act = o.actual_order_amount || {};
  const totalPaid = o.payment_amount != null ? num(o.payment_amount) : num(act.payment_amount);
  const paid = o.paid || '';
  if (paid === 'T' && totalPaid === 0) continue;
  if (paid === 'F') continue;

  const month = String(o.order_date || '').slice(0, 7);
  if (!/^\d{4}-\d{2}$/.test(month)) continue;
  monthsWithData.add(month);

  const mid = o.member_id ? String(o.member_id) : '';
  let gender = '알수없음', age = '알수없음';
  if (mid && memberMap[mid]) {
    gender = genderKo(memberMap[mid].gender);
    age = ageBucket(memberMap[mid].birthday, o.order_date);
  }
  // 네이버와 동일 축 유지: 성별·연령 중 하나라도 모르면 '알수없음' 단일 버킷으로
  if (gender === '알수없음' || age === '알수없음') { gender = '알수없음'; age = '알수없음'; }

  // 구매자 중복 제거 키: 회원ID > 이메일 > 이름+연락처 > 주문번호
  const b = o.buyer || {};
  const buyerKey = mid
    || b.email || o.member_email || o.buyer_email
    || ((b.name || o.buyer_name) ? (b.name || o.buyer_name) + '|' + (b.cellphone || b.phone || o.buyer_cellphone || '') : oid);

  const key = month + '|' + gender + '|' + age;
  if (!agg[key]) agg[key] = { buyers: new Set(), orderCnt: 0, amount: 0 };
  agg[key].buyers.add(buyerKey);
  agg[key].orderCnt += 1;
  agg[key].amount += totalPaid;
}

// 4) 대상 월 목록: 기간 계산 노드의 월 단위 청크 기준 (주문이 없는 달도 0으로 생성)
const months = new Set(monthsWithData);
for (const it of $('기간 계산').all()) {
  const m = String(it.json.start_date || '').slice(0, 7);
  if (/^\d{4}-\d{2}$/.test(m)) months.add(m);
}

// 5) 매월 13개 조합을 모두 출력 (네이버 리포트와 동일)
const AGES = ['10대 이하', '20대', '30대', '40대', '50대', '60대 이상'];
const COMBOS = [];
for (const g of ['남성', '여성']) for (const a of AGES) COMBOS.push([g, a]);
COMBOS.push(['알수없음', '알수없음']);

const now = new Date().toISOString();
const rows = [];
for (const m of [...months].sort()) {
  for (const [g, a] of COMBOS) {
    const v = agg[m + '|' + g + '|' + a];
    rows.push({ json: {
      row_key: [m, g, a].join('_'),
      data_month: m,
      age_group: a,
      gender: g,
      buyers_count: v ? v.buyers.size : 0,
      order_count: v ? v.orderCnt : 0,
